const items = $input.all();

// 🟢 HEADER
const header = {
  invoice_number: items[0].json.invoice_number,
  issue_date: items[0].json.issue_date,
  client: items[0].json.client.trim(),
  currency: items[0].json.currency.trim(),
  total_ht: items[0].json.total_ht,
  total_tva: items[0].json.total_tva,
  total_ttc: items[0].json.total_ttc
};

// 🟢 LINES
const lines = items.map(i => ({
  reference: i.json.reference.trim(),
  designation: i.json.designation.trim(),
  quantity: i.json.quantity,
  unit_price: i.json.unit_price,
  discount: i.json.discount,
  line_total_ht: i.json.line_total_ht
}));

return [
  { json: { type: "header", data: header } },
  { json: { type: "lines", data: lines } }
];

